// Helper function to get all working links
export function getWorkingCarouselLinks(): Array<{ text: string; href: string; selector: string }> {
  return carouselData.carousels.flatMap(carousel => 
    carousel.links
      .filter(link => link.isVisible && link.href && !link.href.includes('#') && !link.href.includes('javascript:'))
      .map(link => ({
        text: link.text,
        href: link.href,
        selector: carousel.selector
      }))
  );
}

// Helper function to get carousels by selector type
export function getCarouselsBySelector(selector: string): CarouselInfo[] {
  return carouselData.carousels.filter(carousel => carousel.selector === selector);
}
